class Solution {
    public int climbStairs(int n) {
        return countWays(n);
    }

    private int countWays(int remaining) {
        if (remaining < 0) return 0;
        if (remaining == 0) return 1;
        return countWays(remaining - 1) + countWays(remaining - 2);
    }
}

