class Solution {
    public int climbStairs(int n) {
        if (n == 1) return 1;
        int oneStepBefore = 1;
        int twoStepsBefore = 2;
        for (int step = 3; step <= n; step++) {
            int current = oneStepBefore + twoStepsBefore;
            oneStepBefore = twoStepsBefore;
            twoStepsBefore = current;
        }
        return twoStepsBefore;
    }
}
